import React from "react";
import { createRoot } from "react-dom/client";
import {
  LineworkComponent,
  tryParseSections,
  type SectionState,
} from "./LineworkComponent";

const elem = document.getElementById("puzzle-content-root");
if (elem) {
  const storage = (window as unknown as { localStorage: Storage }).localStorage;
  const getStorage = (): SectionState[] | null => {
    const raw = storage.getItem("linework-data");
    return tryParseSections(raw);
  };
  const setStorage = (x: string) => {
    storage.setItem("linework-data", x);
  };
  const root = createRoot(elem);
  root.render(
    <LineworkComponent getStorage={getStorage} setStorage={setStorage} />,
  );
} else {
  console.error(
    "Could not mount LineworkComponent because #puzzle-content-root was nowhere to be found",
  );
}
